const ARTICLES = [
  {id:1, cat:"uls-tor", title:"Ерөнхийлөгч У.Хүрэлсүх үүрэгт ажлаасаа чөлөөлөгдөх хүсэлтээ мэдэгдлээ", titleEn:"President U. Khurelsukh announces he will step down", time:"15 мин", timeEn:"15 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Government%20Palace%2C%20Ulaanbaatar.jpg?width=1000", text:"Монгол Улсын Ерөнхийлөгч У.Хүрэлсүх өнөөдөр буюу арваннэгдүгээр сарын 17-нд үүрэгт ажлаасаа чөлөөлөгдөх хүсэлтээ гаргаж буйгаа албан ёсоор мэдэгдлээ. Тэрбээр үд дунд хэвлэлийнхэнд мэдэгдэл хийхдээ өөрт нь тулгараад буй авлигын хэргийн талаарх гүтгэлэг худал болохыг нотлохын тулд албан тушаалаа өгч, жирийн иргэний хувиар шалгуулна гэж мэдэгдсэн байна.\n\nЭнэ хэрэг нь 2019 онд түүнийг Ерөнхий сайдаар ажиллаж байх үед Тавантолгой-Гашуунсухайт чиглэлийн 234 км төмөр зам барих гэрээг тендер зарлалгүйгээр «Боди Интернэшнл» компанид олгосонтой холбоотой юм. Улаанбаатар хотын дарга асан Х.Нямбаатар арваннэгдүгээр сарын 14-нд төмөр замын урьдчилгаа төлбөрөөс 110 сая ам.доллар улс төрчдөд хахууль болон очсон, үүний 25 сая ам.долларыг нь Хүрэлсүх авсан гэж мэдэгдсэн байна. Ерөнхийлөгч үүнийг эрс няцааж, ард түмнээсээ, төрөөсөө хэзээ ч хулгайлж байгаагүй гэж мэдэгджээ.\n\nАрдчилсан намын бүлэг арваннэгдүгээр сарын 16-нд Ерөнхийлөгч болон авлигын хэрэгт нэр холбогдсон бусад албан тушаалтнуудыг огцорч, хуулийн байгууллагаар шалгуулахыг шаардаж, эсрэг тохиолдолд Засгийн газрыг огцруулах асуудал тавьж, Ерөнхийлөгчид импичмент зарлахаа мэдэгдсэн юм. Ерөнхийлөгч Ардчилсан намын шаардлагыг хүлээн авч, ажлаа өгч байна гэж тодотгосон байна.\n\nЕрөнхийлөгчийн Тамгын газрын дарга А.Үйлстөгөлдөрийн мэдээлснээр чөлөөлөгдөх хүсэлтийг өнөөдөр УИХ-д хүргүүлнэ. УИХ-ын Төрийн байгуулалтын байнгын хороо маргааш буюу арваннэгдүгээр сарын 18-нд хэлэлцэж, чуулганы нэгдсэн хуралдаан арваннэгдүгээр сарын 19-нд шийдвэрлэх төлөвтэй байна. Хуульд зааснаар 126 гишүүний олонх буюу 64-өөс доошгүй гишүүн дэмжвэл хүсэлтийг хүлээн авна. Хэрэв УИХ дэмжихгүй бол Ерөнхийлөгч албаа үргэлжлүүлнэ.\n\nХүсэлт хүлээн авагдвал Ерөнхийлөгчийн бүрэн эрхийг УИХ-ын дарга С.Бямбацогт түр хэрэгжүүлж, дөрвөн сарын дотор Ерөнхийлөгчийн ээлжит бус сонгууль зарлан явуулна. Энэ нь Монголын түүхэнд төрийн тэргүүн өөрийн хүсэлтээр албан тушаалаа өгч буй анхны тохиолдол болох юм. Хүрэлсүх 2021 онд Ерөнхийлөгчөөр сонгогдсон бөгөөд өмнө нь өндөр албан тушаалаас өөрийн хүсэлтээр дөрөв дэх удаагаа чөлөөлөгдөж байна.", textEn:"Mongolian President U. Khurelsukh announced today, November 17, that he is submitting a request to be relieved of his duties. Speaking to journalists at midday, he said he would step down and submit to investigation as an ordinary citizen in order to prove that the corruption allegations against him are false.\n\nThe case concerns a contract awarded in 2019, when he was prime minister, to build the 234-kilometre Tavantolgoi-Gashuunsukhait railway without a tender, to the company Bodi International. Former Ulaanbaatar mayor Kh. Nyambaatar said on November 14 that 110 million US dollars from the railway's advance payment had gone to politicians as kickbacks, including 25 million dollars to Khurelsukh. The President strongly denied this, saying he had never stolen from his people or his state.\n\nOn November 16, the Democratic Party caucus demanded that the President and other officials named in the allegations resign and face investigation, warning that otherwise it would move to dismiss the Government and launch impeachment proceedings against the President. Khurelsukh said he accepted the Democratic Party's demand and was stepping down.\n\nAccording to A. Uilstuguldur, head of the President's Office, the request will be submitted to Parliament today. The Standing Committee on State Structure is expected to discuss it tomorrow, November 18, with a plenary session deciding on November 19. Under the law, the request is accepted if a majority of the 126 members — at least 64 — support it. If Parliament does not support it, the President will remain in office.\n\nIf the request is accepted, Parliament Speaker S. Byambatsogt will exercise presidential powers on an interim basis, and an extraordinary presidential election must be called within four months. This would be the first time in Mongolia's history that a head of state has voluntarily stepped down. Khurelsukh was elected President in 2021 and is now leaving a senior post at his own request for the fourth time."},
  {id:2, cat:"uls-tor", title:"Сайд Б.Энхбаяр, дэд сайд Д.Мөнх-Эрдэнэ нар албан тушаалаасаа чөлөөлөгдөх хүсэлтээ өглөө", titleEn:"Minister B. Enkhbayar and Deputy Minister D. Munkh-Erdene ask to step down", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/2024-10-18%20Ulaanbaatar%2C%20Government%20Palace.jpg?width=760", text:"Монгол Улсын сайд, Засгийн газрын Хэрэг эрхлэх газрын дарга Б.Энхбаяр өнөөдөр буюу арваннэгдүгээр сарын 17-нд үүрэгт ажлаасаа өөрийн хүсэлтээр чөлөөлөгдөх өргөдлөө Ерөнхий сайдад өглөө. Тэрбээр хууль хяналтын байгууллагаар шалгуулж, нэр төрөө сэргээлгэх зорилгоор ийм шийдвэр гаргаснаа сэтгүүлчдэд мэдэгдсэн байна.\n\nМөн өдөр Хууль зүй, дотоод хэргийн дэд сайд Д.Мөнх-Эрдэнэ албан тушаалаасаа чөлөөлөгдөх хүсэлтээ Ерөнхий сайдад гаргаснаа мэдэгдлээ. Тэрбээр цаашид ард түмний баялгийг хулгайлсан гэмт хэргийн бүлэглэлтэй тууштай тэмцэж, Монгол төрийг авлигачдаас цэвэрлэх үйлсэд хүч хавсран зүтгэх болно гэж мэдэгдсэн байна.\n\nХоёр албан тушаалтны шийдвэр нь Ерөнхийлөгч У.Хүрэлсүх үүрэгт ажлаасаа чөлөөлөгдөх хүсэлтээ мэдэгдсэнтэй нэг өдөр гарсан нь улс төрийн хүрээнд ихээхэн анхаарал татаж байна. Сүүлийн өдрүүдэд Тавантолгойн төмөр замын урьдчилгаа төлбөртэй холбоотой 110 сая ам.долларын авлигын хэрэг олон нийтийн анхаарлын төвд байгаа бөгөөд нэр холбогдсон албан тушаалтнуудыг огцорч шалгуулахыг Ардчилсан нам шаардаж байгаа юм.\n\nЗасгийн газар хоёр албан тушаалтны хүсэлтийг хууль, журмын дагуу шийдвэрлэх ёстой. Тэдний орон гарсан суудалд хэн томилогдох нь ойрын өдрүүдэд тодорхой болох төлөвтэй байна.", textEn:"B. Enkhbayar, Minister and Chief of the Cabinet Secretariat, submitted a request today, November 17, asking the Prime Minister to relieve him of his duties at his own request. He told journalists that he made the decision in order to be investigated by law enforcement and to clear his name.\n\nOn the same day, Deputy Minister of Justice and Home Affairs D. Munkh-Erdene also submitted a request to the Prime Minister to be relieved of his post. He said he would continue to fight resolutely against the criminal group that had stolen the people's wealth and work to cleanse the Mongolian state of corruption.\n\nThe two officials' decisions came on the same day that President U. Khurelsukh announced his request to step down, drawing wide attention in political circles. In recent days, the alleged 110-million-US-dollar corruption case linked to the advance payment for the Tavantolgoi railway has been at the centre of public attention, and the Democratic Party has demanded that the officials named in it resign and face investigation.\n\nThe Government must decide on both requests in accordance with the law. Who will fill the vacated posts is expected to become clear in the coming days."},
  {id:3, cat:"ediin-zasag", title:"УИХ-ын дарга: зээлийн өндөр хүүг бууруулж, Санхүүгийн зохицуулах хороог нээлттэй сонгон шалгаруулна", titleEn:"Speaker: high loan interest must fall as financial regulator faces open selection", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolbank%20headquarters%20Ulaanbaatar.jpg?width=760", text:"Улсын Их Хурлын дарга С.Бямбацогт өнөөдөр буюу арваннэгдүгээр сарын 17-нд санхүүгийн салбарын мэргэжлийн таван холбооны удирдлагыг хүсэлтийнх нь дагуу хүлээн авч уулзлаа. Монголын даатгалын зах зээлийн холбоо, Үл хөдлөх хөрөнгийн бизнес эрхлэгчдийн нэгдсэн холбоо, Монголын үнэт цаасны арилжаа эрхлэгчдийн холбоо, Монголын хохирол үнэлгээчдийн холбоо, Монголын банк бус санхүүгийн байгууллагуудын холбоод хамтран арваннэгдүгээр сарын 11-нд УИХ-ын даргад хандаж, Санхүүгийн зохицуулах хорооны удирдлагыг мэргэжлийн чадвар, туршлага, ёс зүй, хараат бус байдал, ил тод шалгуурт тулгуурлан томилохыг хүссэн байна.\n\nУулзалтын үеэр УИХ-ын дарга «УИХ таныг сонсож байна» цэсээр дамжуулан иргэдийн ирүүлж буй 1000 гаруй саналын дийлэнх нь эдийн засгийн дарамт, зээлийн өндөр хүүг бууруулах тухай асуудал байгааг онцолсон байна. Тэрбээр зургаан сарын өмнө Санхүүгийн зохицуулах хорооны удирдлагад зээл, зээлийн хүүг бууруулахтай холбоотой дөрвөн тодорхой асуудлаар үр дүн гаргаж ажиллахыг чиглэл болгосон ч хорооны дарга албан тушаалаасаа чөлөөлөгдөх хүсэлтээ гаргасан гэж мэдэгджээ.\n\nС.Бямбацогт дараагийн томилгоог хийхдээ иргэдийн өмнө тулгамдаад буй хэтийдсэн өндөр зээлийн хүүг бууруулах чиглэлээр бодит ажил хийх шалгуурыг нэгдүгээрт тавьж, нээлттэй сонгон шалгаруулалтаар томилох болно гэж онцлон тэмдэглэлээ. Тэрбээр «Зээл бүрийн цаана иргэдийн цөхөрсөн итгэл бий. Үүнийг шийдэх ёстой» гэж байр сууриа илэрхийлсэн байна.\n\nУИХ-ын даргын мэдээлснээр банк бус санхүүгийн салбар 2025 онд 900 гаруй тэрбум төгрөгийн цэвэр ашигтай ажиллаж байхад эсрэгээрээ иргэдийн өрийн дарамт улам өссөн байна. Санхүүгийн зохицуулах хороо өнгөрсөн аравдугаар сарын 21-нд зээлийн сарын хүүгийн дээд хэмжээг 4.5 хувь байхаар тогтоосон нь иргэд жилийн дүнгээр 54 хувийн хүүтэй зээл төлж байна гэсэн үг юм. Хорооны даргын чөлөөлөгдөх хүсэлтийг УИХ хууль, журмын дагуу шийдвэрлэнэ.", textEn:"Speaker of the State Great Khural S. Byambatsogt met today, November 17, with the leaders of five professional associations in the financial sector at their request. The Mongolian Insurance Market Association, the Association of Real Estate Business Owners, the Association of Securities Traders, the Association of Loss Assessors and the Association of Non-Bank Financial Institutions jointly wrote to the Speaker on November 11, asking that the leadership of the Financial Regulatory Commission be appointed on the basis of professional competence, experience, ethics, independence and transparent criteria.\n\nDuring the meeting, the Speaker noted that most of the more than 1,000 proposals submitted by citizens through the «Parliament is listening to you» channel concern economic pressure and lowering high loan interest rates. He said that six months ago he had instructed the Commission's leadership to deliver results on four specific issues related to lowering loan interest, but the Commission's chair had since submitted a request to step down.\n\nByambatsogt stressed that the next appointment would be made through open selection, with the top criterion being real work to lower the excessively high loan interest burdening citizens. «Behind every loan there is the dashed trust of citizens. This must be resolved,» he said.\n\nAccording to the Speaker, the non-bank financial sector earned more than 900 billion tugriks in net profit in 2025, while household debt burdens continued to grow. On October 21, the Financial Regulatory Commission set the maximum monthly loan interest rate at 4.5 percent, meaning citizens pay 54 percent interest a year. Parliament will decide on the Commission chair's resignation in accordance with the law."},
  {id:4, cat:"ediin-zasag", title:"LendMN Европын Сэргээн Босголт Хөгжлийн Банктай 10 сая ам.долларын санхүүжилтийн гэрээ байгуулав", titleEn:"LendMN signs $10 million financing deal with European Bank for Reconstruction and Development", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Ulaanbaatar%20skyline.jpg?width=760", text:"Финтекийн компани LendMN Европын Сэргээн Босголт Хөгжлийн Банктай 10 сая ам.долларын санхүүжилтийн гэрээ байгууллаа. Энэ нь финтекийн салбарт анх удаа олон улсын хөгжлийн банкнаас залуучуудын бизнесийг дэмжих санхүүжилт татсан тохиолдол болж, LendMN-ийн 10 жилийн итгэлцлийн баталгаа болсон гэж компани мэдээлжээ.\n\nТус санхүүжилтээр 34 хүртэлх насны бизнес эрхлэгчдэд 1.99 хувийн хүүтэй, барьцаагүй, 100 хувь дижитал зээл олгоно. Залуу бизнес эрхлэгчдийг дэмжих нь тус санхүүжилтийн гол зорилго бөгөөд дижитал зээлийн хүртээмжийг нэмэгдүүлэхэд чиглэж байна.\n\nLendMN нь Монголын финтекийн салбарын тэргүүлэгч компаниудын нэг бөгөөд сүүлийн жилүүдэд залуу бизнес эрхлэгчид болон иргэдэд дижитал санхүүгийн үйлчилгээ үзүүлж ирсэн юм. Олон улсын хөгжлийн банкнаас санхүүжилт татсан нь компанийн засаглал, ил тод байдалд итгэл үзүүлсэн хэрэг гэж үзэж байна.", textEn:"Fintech company LendMN has signed a 10-million-US-dollar financing agreement with the European Bank for Reconstruction and Development. The company said it is the first time a fintech firm has attracted funding from an international development bank to support youth businesses, and that it stands as proof of LendMN's ten years of trust.\n\nUnder the agreement, entrepreneurs aged up to 34 will receive unsecured, fully digital loans at 1.99 percent interest. Supporting young entrepreneurs is the main aim of the funding, which is designed to expand access to digital lending.\n\nLendMN is one of Mongolia's leading fintech companies and has provided digital financial services to young entrepreneurs and citizens in recent years. Attracting funding from an international development bank is seen as a vote of confidence in the company's governance and transparency."},
  {id:5, cat:"niigem", title:"Өнөөдөр Сэлэнгэ, Хэнтийн хойд нутгаар цас орж, ихэнх нутгаар хүйтэрнэ", titleEn:"Snow in Selenge and northern Khentii today as cold grips most of the country", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Winter%20Storm%20Nemo%20Destruction.jpg?width=760", text:"Цаг уур, орчны шинжилгээний газраас цаг агаарын аюултай үзэгдлээс сэрэмжлүүлж байна. Өнөөдөр буюу арваннэгдүгээр сарын 18-нд Сэлэнгэ, Хэнтийн хойд, Төв аймгийн зүүн хойд, Дорнодын зарим сумдын нутгаар 0.0-2.0 миллиметр цас орж, цасан шуурга шуурна. Салхи говь, тал, хээрийн нутгаар секундэд 14-16 метр хүрч ширүүсч, зам, даваа, гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэхийг малчид, иргэд, тээвэрчдэд анхааруулж байна.\n\nШөнөдөө Дархадын хотгор, Завхан, Заг, Байдраг голын эх, Хүрэнбэлчир орчмоор 27-32 хэм, Алтай, Хангай, Хөвсгөл, Хэнтийн уулархаг нутаг, голын хөндийгөөр 20-25 хэм, говийн бүс нутгийн өмнөд хэсгээр 8-13 хэм, бусад нутгаар 14-19 хэм хүйтэн байна. Өдөртөө уулархаг нутгаар 15-20 хэм, говийн бүс нутгийн өмнөд хэсгээр 1 хэм хүйтнээс 6 хэм, бусад нутгаар 7-12 хэм хүйтэн байх төлөвтэй байна.\n\nУлаанбаатар хот орчмоор өнөөдөр үүлшинэ, ялимгүй цас орно. Салхи баруун хойноос секундэд 5-10 метр, шөнөдөө Яармаг-Сонгины орчмоор 17-19 хэм, бусад хэсгээр 14-16 хэм, өдөртөө 6-8 хэм хүйтэн байна. Өглөөний байдлаар нийслэлд -15 хэм хүйтэн, үүлэрхэг байгаа юм.\n\nАрваннэгдүгээр сарын 19-20-нд Сэлэнгийн зүүн, Хэнтий, Дорнод, Сүхбаатарын зарим сумдын нутгаар цас орж, цасан шуурга шуурна. Иргэд хол замд гарахдаа бэлтгэлтэй байж, цаг агаарын мэдээг тогтмол авахыг цаг уурын байгууллагаас зөвлөж байна.", textEn:"The National Agency for Meteorology and Environmental Monitoring has warned of dangerous weather. Today, November 18, snow of 0.0-2.0 millimetres and blizzards are expected in Selenge, northern Khentii, north-eastern Tuv and some soums of Dornod. Winds will strengthen to 14-16 metres per second across the Gobi, steppe and field regions, and herders, residents and drivers are warned that visibility will be limited on roads, passes and hills, with slippery conditions and icing.\n\nOvernight temperatures will fall to minus 27-32 degrees in the Darkhad depression, the headwaters of the Zavkhan, Zag and Baidrag rivers and around Khurenbelchir, minus 20-25 in the Altai, Khangai, Khuvsgul and Khentii mountains and river valleys, minus 8-13 in the southern Gobi, and minus 14-19 elsewhere. During the day it will be minus 15-20 in the mountains, minus 1 to plus 6 in the southern Gobi, and minus 7-12 elsewhere.\n\nAround Ulaanbaatar today it will be mostly cloudy with slight snow. Winds from the north-west at 5-10 metres per second; overnight minus 14-16 degrees, minus 17-19 in the Yaarmag-Songino area, and minus 6-8 during the day. This morning the capital is at minus 15 degrees and cloudy.\n\nOn November 19-20, snow and blizzards are expected in eastern Selenge and some soums of Khentii, Dornod and Sukhbaatar. The weather agency advises residents to prepare carefully before long journeys and to follow weather updates regularly."},
  {id:6, cat:"oron-nutag", title:"ХОВД: Цасанд боогдсон хоёр айлыг 2100 бог малтай нь уулнаас буулгалаа", titleEn:"KHOVD: Two snowbound herder families rescued with 2,100 head of livestock", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Herding%20sheep%2C%20Inner%20Mongolia%20Oct%202001.jpg?width=760", text:"Ховд аймгийн Эрдэнэбүрэн сумын Баянгол багийн «Тагийн-Орой» гэдэг газар арваннэгдүгээр сарын 13-наас хойш 50-70 сантиметр зузаан цас орсны улмаас зам даваа хаагдаж, уулан дээр өвөлжиж байсан хоёр айл цасанд боогдсон тухай дуудлагыг арваннэгдүгээр сарын 15-ны 11:20 цагт хүлээн авсан байна. Тус газар нь аймгийн төвөөс зүүн хойд зүгт 115 км, сумын төвөөс зүүн хойд зүгт 35 км зайд оршдог.\n\nТус аймгийн Онцгой байдлын газрын аврах ангийн алба хаагчид, мэргэжлийн ангийн ажилтнууд, ар гэрийнхэн хамтран аврах ажиллагаа явуулжээ. Малчин Г /55 настай, эрэгтэй/, О /55 настай, эмэгтэй/, Б /31 настай, эрэгтэй/ нарыг 1400 бог малтай нь арваннэгдүгээр сарын 16-ны 10:09 цагт уулнаас буулгасан байна.\n\nМөн малчин Б /34 настай, эрэгтэй/, Б /32 настай, эмэгтэй/ нар 16 хоногтой нярай хүүхдийн хамт 700 бог малтайгаа мөн өдрийн 12:00 цагт уулнаас буужээ. Ийнхүү нийт хоёр айл, 2100 бог малыг аюулгүй газарт хүргэсэн байна.\n\nСүүлийн өдрүүдэд баруун аймгуудаар их цас орж, зам даваа хаагдаж байгаа тул малчид, иргэд хол замд гарахдаа онцгой байдлын байгууллагад мэдэгдэж, цаг агаарын мэдээг тогтмол авахыг анхааруулж байна.", textEn:"A call was received at 11:20 on November 15 reporting that two herder families wintering in the mountains were snowbound at a place called Tagin-Oroi in Bayangol bag, Erdeneburen soum, Khovd aimag, after 50-70 centimetres of snow fell there from November 13, closing roads and passes. The site lies 115 kilometres north-east of the aimag centre and 35 kilometres north-east of the soum centre.\n\nRescuers from the aimag Emergency Department's rescue unit, professional unit staff and family members carried out the rescue operation. Herders G (male, 55), O (female, 55) and B (male, 31) were brought down from the mountain with 1,400 head of small livestock at 10:09 on November 16.\n\nHerders B (male, 34) and B (female, 32), together with their 16-day-old baby, were also brought down with 700 head of small livestock at noon the same day. In total, two families and 2,100 head of livestock were brought to safety.\n\nHeavy snow has fallen in the western aimags in recent days, closing roads and passes, so herders and residents are urged to notify emergency services before long journeys and to follow weather updates regularly.", region:"khovd"},
  {id:7, cat:"delhii", title:"АНУ Ираны Кешм арал дахь пуужингийн байгууламж руу цохилт өглөө", titleEn:"US strikes missile site on Iran's Qeshm Island", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/QeshmIsland%20NASA.jpg?width=760", text:"АНУ-ын сөнөөгч онгоцууд өнөөдөр буюу арваннэгдүгээр сарын 17-ны орой Хормузын хоолойд орших Ираны Кешм арал дахь Исламын хувьсгалын хамгаалалтын корпусын пуужин хөөргөх байгууламж руу нарийн цохилт өглөө. АНУ-ын цэргийн албан тушаалтны мэдээлснээр цохилт нь Бахрейн дахь АНУ-ын бааз руу Ираны хийсэн дроны довтолгоонд хариу барьсан өөрийгөө хамгаалах ажиллагаа байсан байна.\n\nИраны тал Кешм арал дээр таваас зургаан дэлбэрэлт сонсогдсон гэж мэдээлсэн бөгөөд Хормозган мужийн орлогч захирагч Ахмад Нафиси орон сууц, худалдаа, дэд бүтцийн бүсэд хохирол учраагүй, нөхцөл байдал хяналтад байна гэж мэдэгджээ. АНУ-ын Төв командлал Бахрейн дахь Шейх Иса агаарын баазын радарын системийг онилсон Ираны хэд хэдэн дроныг ямар ч хохиролгүйгээр таслан зогсоосон гэж мэдээлсэн байна.\n\nИраны тал өнөөдөр Бахрейн дахь АНУ-ын цэргийн байгууламж руу гурав дахь удаагаа довтолсон нь сүүлийн таван хоногт хийсэн гурав дахь довтолгоо болжээ. Үүний зэрэгцээ Ираны Хувьсгалын хамгаалалтын корпус Кешм арлын өмнөд хэсэгт АНУ-ын MQ-1 тагнуулын дроныг устгасан гэж мэдэгдсэн байна. Ираны тэнгисийн цэргийн мэдээлснээр Хормузын хоолойд сүүлийн 24 цагийн дотор гурван танкер минад өртөж шатсан бөгөөд хоёр сая гаруй баррель нефть тээвэрлэж явсан супертанкер ч минад өртсөн байна.\n\nАНУ, Израиль хоёрдугаар сарын 28-нд Ираны эсрэг хамтарсан цохилт өгснөөс хойш Персийн булангийн бүсэд мөргөлдөөн эрчимжиж байна. АНУ-ын Ерөнхийлөгч Дональд Трамп Тегераныг анхааруулж, Ираныг Вашингтонд «бохир бөмбөг» дэлбэлэхээр төлөвлөж байгаа тухай АНУ-ын тагнуулын мэдээлэл гарсан гэж мэдээлжээ. Хормузын хоолой нь дэлхийн нефтийн нийлүүлэлтийн чухал суваг тул үйл явдал эрчим хүчний зах зээлд түгшүүр төрүүлж байна.", textEn:"US fighter jets struck a missile launch site belonging to Iran's Islamic Revolutionary Guard Corps on Qeshm Island in the Strait of Hormuz this evening, November 17. A US military official said the precision strike was a self-defence operation in response to an Iranian drone attack on a US base in Bahrain.\n\nIranian media reported five to six explosions on Qeshm Island, while Hormozgan deputy governor Ahmad Nafisi said the strikes caused no damage to residential, commercial or infrastructure areas and that the situation was under control. US Central Command said it intercepted several Iranian drones aimed at the radar system at Sheikh Isa Air Base in Bahrain without any damage to US equipment or personnel.\n\nTuesday's attack was Iran's third strike on US military facilities in Bahrain in five days. At the same time, the Revolutionary Guard Corps said it had shot down a US MQ-1 reconnaissance drone south of Qeshm Island. Iran's navy said three tankers had caught fire after hitting mines in the Strait of Hormuz in the past 24 hours, including a supertanker carrying more than two million barrels of oil.\n\nTensions in the Persian Gulf have escalated since the US and Israel launched joint strikes against Iran on February 28. US President Donald Trump has warned Tehran, and US intelligence reports have suggested Iran is planning to detonate a so-called dirty bomb in Washington. Because the Strait of Hormuz is a crucial channel for global oil supplies, the clashes are causing alarm on energy markets."},
  {id:8, cat:"delhii", title:"Манилагийн Квад дээд хэмжээний уулзалт: чухал эрдэс бодисын гэрээ, таван үр дүн", titleEn:"Manila Quad summit agrees critical minerals deals and five outcomes", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20in%20Manila%2016.jpg?width=760", text:"АНУ, Австрали, Энэтхэг, Япон улсын удирдагчид өнөөдөр буюу арваннэгдүгээр сарын 17-нд Филиппиний Манила хотод Квад буюу дөрвөн талт аюулгүй байдлын яриа хэлэлцээний дээд хэмжээний уулзалтыг хийлээ. Уулзалт нь АСЕАН-ы 49 дэх дээд хэмжээний уулзалтын хажуугаар болж, 2024 оны есдүгээр сард АНУ-ын Вилмингтонд болсноос хойших анхны биечлэн хийсэн дээд хэмжээний уулзалт болсон юм.\n\nУулзалтад АНУ-ын Ерөнхийлөгч Дональд Трамп, Энэтхэгийн Ерөнхий сайд Нарендра Моди, Японы Ерөнхий сайд Такаичи Санаэ, Австралийн Ерөнхий сайд Энтони Албанизи оролцлоо. Энэ нь Трампын хоёр дахь бүрэн эрхийн хугацаанд хийсэн анхны Квад дээд хэмжээний уулзалт бөгөөд аравдугаар сард албан тушаалдаа орсон Такаичид оролцсон анхны уулзалт байлаа.\n\nТрамп уулзалтын дараа дөрвөн улс чухал эрдэс бодис, ховор элементийн нийлүүлэлтийн сүлжээг бэхжүүлэх талаар хэд хэдэн чухал гэрээнд хүрсэн гэж мэдэгдлээ. Тэрбээр «Бид ховор элементийг өмнө нь хэзээ ч байгаагүй хэмжээнд үйлдвэрлэж байна. Бид 10 сарын дотор тэднийг гүйцнэ» гэж мэдэгдсэн байна. Моди Ерөнхий сайд Квадыг «шийдэл гаргадаг итгэлтэй түншлэл» гэж тодорхойлжээ.\n\nУдирдагчид таван үр дүнг зарласан байна: Квадын бизнесийн удирдагчдын форум /2027 оны эхээр Энэтхэгийн Мумбай хотод болно/, терроризмтой тэмцэх хамтын ажиллагаа, Энэтхэг-Номхон далайн тэнгисийн хяналтын хамтын ажиллагаа, кабелийн холболт, тэсвэрлэх чадварын түншлэл, кибер хамтын ажиллагааг бэхжүүлэх. Дөрвөн улсын экспортын зээлийн агентлагууд хамтарсан төслүүдийн санхүүжилтийг хэлэлцэхээр маргааш Токиод уулзана. Трамп Модиг «маш хатуу хүн» гэж нэрлэж, дөрвөн удирдагчийг «гайхалтай хүмүүс» гэж магтсан байна.", textEn:"The leaders of the United States, Australia, India and Japan held a Quad summit in Manila, Philippines, today, November 17. The meeting took place on the sidelines of the 49th ASEAN Summit and was the first in-person Quad leaders' summit since Wilmington, United States, in September 2024.\n\nUS President Donald Trump, Indian Prime Minister Narendra Modi, Japanese Prime Minister Sanae Takaichi and Australian Prime Minister Anthony Albanese took part. It was the first Quad summit of Trump's second term and the first attended by Takaichi, who took office in October.\n\nAfter the meeting, Trump said the four countries had reached several key agreements to strengthen supply chains for critical minerals and rare earths. «We are making rare earth at a level that we've never made before. We're gonna catch them within 10 months,» he said. Prime Minister Modi described the Quad as a «trusted partnership» that delivers solutions.\n\nThe leaders announced five outcomes: a Quad Business Leaders' Forum, to be held in Mumbai, India, in early 2027; counterterrorism cooperation; Indo-Pacific maritime surveillance collaboration; a partnership for cable connectivity and resilience; and enhanced cyber cooperation. The four countries' export credit agencies will meet in Tokyo tomorrow to discuss financing for joint projects. Trump called Modi a «very tough man» and praised the four leaders as «phenomenal people»."},
  {id:9, cat:"delhii", title:"Украин Керчийн гүүрийг хоёр дахь өдрөө онилж, Орос Киев рүү цохилт өглөө", titleEn:"Ukraine strikes Kerch Bridge for second day as Russia hits Kyiv", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Crimean%20Bridge%201.jpg?width=760", text:"Украины зэвсэгт хүчин Крымийг Орост холбосон Керчийн гүүрийг хоёр дахь өдрөө онилж, өнгөрсөн шөнө Орос руу 1300 гаруй дрон илгээж, энэ оны хоёр дахь хамгийн том шөнийн довтолгоог хийлээ. Гүүрэн дээрх хөдөлгөөн тасалдсан бөгөөд Оросын тал 1336 дроныг таслан зогсоосон гэж мэдэгдсэн байна.\n\nДовтолгооны зорилтуудад Оросын нефть химийн дэд бүтэц, батлан хамгаалах үйлдвэрлэл, пуужин үйлдвэрлэх, хөөргөх байгууламжууд багтсан тухай Дайныг судлах хүрээлэн мэдээлжээ. Украины тал Оросын дайны чадавхыг сулруулахын тулд алсын зайн цохилтоо эрчимжүүлж байгаа бөгөөд энэ нь дайны шинэ шатанд орж байгааг харуулж байна. Үүний зэрэгцээ Орос Киев хотын гүүрнүүд рүү цохилт өгсөн гэж мэдээлжээ.\n\nҮүний зэрэгцээ Украины Ерөнхийлөгч Володимир Зеленский АНУ анх удаа Донбассын бүс нутгийг НАТО-гийн гишүүнчлэлийн хариуд солилцох санал тавьсан тухай мэдэгдлээ. Тэрбээр ийм тохиролцоог бүх нийтийн санал асуулгаар шийдвэрлэх нөхцөл тавьсан байна. АНУ-ын зуучлалтайгаар Абу Дабид болсон Орос-Украины хэлэлцээ арваннэгдүгээр сарын 11-нд өндөрлөж, олзлогдогсдыг солилцох асуудлаар ахиц гарснаас өөр газар нутаг, аюулгүй байдлын баталгааны талаар тохиролцоонд хүрч чадаагүй байна.\n\nЕвропын Холбоо Украиныг дэмжих 45 тэрбум еврогийн зээлийн төлөвлөгөөг лхагва гарагт гишүүн орнуудад танилцуулахаар төлөвлөж байна. Цөмийн аюулгүй байдлын зохицуулагчид энэ өвөл Украинд цөмийн ослын эрсдэл нэмэгдэж байгааг анхааруулжээ.", textEn:"Ukrainian forces targeted the Kerch Bridge linking Crimea to Russia for a second consecutive day, launching more than 1,300 drones at Russia overnight in the second-largest overnight attack of the year. Traffic on the bridge was disrupted, and Russia said it intercepted 1,336 drones.\n\nThe strikes targeted Russian petrochemical infrastructure, defence industry facilities and missile production and launch sites, according to the Institute for the Study of War. Ukraine is intensifying its long-range strikes to weaken Russia's war capacity, a sign that the war is entering a new phase. At the same time, Russia struck bridges in Kyiv, according to reports.\n\nUkrainian President Volodymyr Zelensky said the United States had for the first time proposed exchanging the Donbas region for NATO membership. He set the condition that such a deal be decided by referendum. US-mediated talks between Russia and Ukraine in Abu Dhabi ended on November 11, with progress only on expanding prisoner exchanges and no agreement on territory or security guarantees.\n\nThe European Union plans to present a 45-billion-euro loan plan for Ukraine to member states on Wednesday. Nuclear safety regulators have warned that the risk of a nuclear accident in Ukraine is increasing this winter."},
  {id:10, cat:"delhii", title:"COP31: чулуужсан түлшний талаарх санал зөрөлдөөн үргэлжилж, ЕХ цэвэр эрчим хүч рүү шилжихийг уриаллаа", titleEn:"COP31: fossil fuel divide persists as EU urges clean energy shift", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/07580%20Kemerk%C3%B6y-Ka%C5%9F-Antalya%2C%20Turkey%20-%20panoramio.jpg?width=760", text:"Туркийн Анталья хотод болж буй НҮБ-ын уур амьсгалын өөрчлөлтийн тухай 31 дүгээр бага хурал буюу COP31-ийн хоёр дахь буюу эцсийн долоо хоног эхэлж, сайд нар өнөөдөр өндөр түвшний хэлэлцээнд оролцлоо. Австрали улс хэлэлцээг удирдаж байгаа бөгөөд даваа гарагт танилцуулсан 18 хуудас бүхий анхны төсөлд дасан зохицох санхүүжилтийг 2035 он гэхэд 120 тэрбум ам.доллар болгон гурав дахин нэмэгдүүлэхийг уриалсан байна.\n\nТөсөлд чулуужсан түлшний талаар хоёр өөр томъёолол багтсан нь санал зөрөлдөөнийг харуулж байна. Нэг нь 2023 онд тохиролцсон «чулуужсан түлшнээс татгалзах» гэсэн үгийг давтаж байгаа бол нөгөө нь илүү зоримог «үе шаттайгаар бүрэн зогсоох» тухай дурдсан байна. Мөн цахилгаан эрчим хүчний эзлэх хувийг 2035 он гэхэд 35 хувьд хүргэх, дасан зохицох санхүүжилтийг нэмэгдүүлэх тухай тусгасан байна.\n\nЕвропын Холбооны уур амьсгалын асуудал хариуцсан комиссар Вопке Хукстра төсөл нь хүлэмжийн хийн ялгарлыг тогтвортой бууруулах хэрэгцээнээс анхаарлыг сарниулж байна гэж мэдэгдэж, COP31-ийн хэлэлцээ цэвэр эрчим хүч рүү шилжих талаар «хамгийн хүчтэй дохио» өгөх ёстой гэж уриаллаа. Австралийн уур амьсгалын сайд Крис Боуэн төсөл нь эцсийн хувилбар биш, харин хэлэлцээний эхлэл гэдгийг онцолсон байна.\n\nХуралд 194 төлөөлөгчийн газар, 100 мянга орчим хүн оролцож байгаа бөгөөд албан ёсны хаалт баасан гарагт болох ч өмнөх хурлууд хугацаанаасаа хэтэрч байсан удаатай. Далайн асуудлаар 95 гаруй хувь нь эрэг орчмын болон арлын улс орнууд уур амьсгалын төлөвлөгөөндөө далайн арга хэмжээг тусгасан тухай шинэ судалгаа гарсан бол 23 улс ойн түймрээс урьдчилан сэргийлэх Антальягийн үйл ажиллагааны төлөвлөгөөг дэмжжээ. Хиймэл оюуны амлалтад 80 байгууллага нэгдсэн ч ердөө есөн улс гарын үсэг зурсан байна.", textEn:"The second and final week of COP31, the 31st UN Climate Change Conference, has begun in Antalya, Türkiye, with ministers arriving for the high-level segment today. Australia is chairing the negotiations, and the first 18-page draft circulated on Monday urges tripling adaptation finance to 120 billion US dollars by 2035.\n\nThe draft contains two different wordings on fossil fuels, reflecting the divide between delegations. One repeats the 2023 wording of «transitioning away» from fossil fuels, while a more ambitious clause speaks of phasing them out. The draft also calls for raising electricity's share of final energy demand to 35 percent by 2035 and increasing adaptation finance.\n\nEU climate commissioner Wopke Hoekstra said the draft distracted from the need for sustained reductions in greenhouse gas emissions, which are mainly caused by burning oil, gas and coal, and urged COP31 to send the «strongest possible signal» on the shift to clean energy. Australian Climate Minister Chris Bowen stressed that the draft is not final but a starting point for negotiations.\n\nSome 194 delegations and around 100,000 people are attending the conference, which is officially due to close on Friday, although previous conferences have run past their deadlines. On oceans, new research finds that more than 95 percent of coastal and island nations include ocean measures in their climate plans, and 23 countries endorsed the Antalya Action Plan on Integrated Fire Management. Eighty entities have joined the artificial intelligence pledge, but only nine countries have signed it."},
  {id:11, cat:"delhii", title:"Канад, Хятад АПЕК-ийн өмнө худалдааны хамтын ажиллагаагаа өргөжүүллээ", titleEn:"Canada and China extend trade cooperation ahead of APEC summit", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Centre%20Block%20-%20Parliament%20Hill.jpg?width=760", text:"Канад, Хятад хоёр улс Ази, Номхон далайн эдийн засгийн хамтын ажиллагааны буюу АПЕК-ийн дээд хэмжээний уулзалтын өмнө худалдааны хамтын ажиллагаагаа өргөжүүлэхээр тохиролцлоо. Хятадын дарга Си Жиньпин Канадын Ерөнхий сайд Марк Карнитай уулзаж, хоёр улсын худалдаа, эдийн засгийн харилцааг өргөжүүлэх талаар ярилцсан байна.\n\nУулзалт нь АНУ-тай хийж буй худалдааны хэлэлцээнд хүндрэл учирч байгаа үед болж байгаа бөгөөд Карни хэрэв Трампын засаг захиргаатай хийж буй худалдааны хэлэлцээ бүтэлгүйтвэл Канад Хятадын автомашин үйлдвэрлэгчидтэй хамтран ажиллах боломжтой гэж мэдэгдсэн байна. Энэ нь Канад худалдааны түншүүдээ төрөлжүүлэхээр эрэлхийлж байгааг харуулж байна.\n\nАПЕК-ийн дээд хэмжээний уулзалт Хятадын Шэньжэнь хотод болох бөгөөд бүс нутгийн худалдаа, эдийн засгийн хамтын ажиллагаа гол сэдэв болох төлөвтэй байна. Канад, Хятадын харилцаа сүүлийн жилүүдэд хүйтэн байсан ч хоёр тал эдийн засгийн хамтын ажиллагааг сэргээхэд сонирхолтой байгааг ажиглагчид тэмдэглэж байна.", textEn:"Canada and China have agreed to extend their trade cooperation ahead of the Asia-Pacific Economic Cooperation, APEC, summit. Chinese President Xi Jinping met Canadian Prime Minister Mark Carney to discuss expanding trade and economic ties between the two countries.\n\nThe meeting comes as Canada's trade talks with the United States face difficulties, and Carney has said Canada could turn to Chinese automakers if trade negotiations with the Trump administration fail. The remark shows Canada is looking to diversify its trading partners.\n\nThe APEC summit will be held in Shenzhen, China, with regional trade and economic cooperation expected to be the main theme. Although Canada-China relations have been cool in recent years, observers note that both sides are interested in reviving economic cooperation."},
  {id:12, cat:"tech", title:"Женсен Хуан Нвидиагийн гүйцэтгэх захирлаар эргэн ирэхэд бэлэн байгаагаа мэдэгдлээ", titleEn:"Jensen Huang says he is ready to return as Nvidia CEO", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Director%20L%C3%AA%20Nguy%E1%BB%85n%20Thi%C3%AAn%20Nga%20and%20NVIDIA%20Founder%20and%20CEO%20Jensen%20Huang.jpg?width=760", text:"Нвидиагийн үүсгэн байгуулагч Женсен Хуан өнөөдөр буюу арваннэгдүгээр сарын 17-нд компанийн төлөөлөн удирдах зөвлөл хүсвэл гүйцэтгэх захирлын албан тушаалд эргэн ирэхэд бэлэн байгаагаа мэдэгдлээ. Тэрбээр «Хэрэв төлөөлөн удирдах зөвлөл миний эргэн ирэлт хувьцаа эзэмшигчид, ажилтнууд, компани болон Америкийн эрх ашигт нийцнэ гэж шийдвэл би тэдний дуудлагад хариулж, гүйцэтгэх захирлаар эргэн ирэхдээ нэр төрийн хэрэг гэж үзнэ» гэж бичжээ. Энэ нь түүнийг өнгөрсөн долоо хоногт огцорсноос хойших анхны олон нийтийн мэдэгдэл боллоо.\n\nХуан арваннэгдүгээр сарын 12-нд гэр бүлээс гадуурх харилцааны талаарх мэдээллүүдийн дараа огцорсон бөгөөд одоо санхүүгийн захирал Колетт Кресс түр гүйцэтгэх захирлаар ажиллаж байна. Төлөөлөн удирдах зөвлөл байнгын залгамжлагчийг хайж байгаа бөгөөд мэдээллээр зөвлөл Хуаныг эргэн ирэх асуудлыг хэлэлцэхгүй байгаа аж. Зөвлөл одоо хайлтын фирм сонгох шатандаа явж, дотоод, гадаад нэр дэвшигчдийг авч үзэж байна.\n\nАНУ-ын Ерөнхийлөгч Дональд Трамп даваа гарагт Хуаныг эргэн ирэхэд «таагүйцэхгүй» гэж мэдэгдсэн бол Сангийн сайд Скотт Бессент компанийн хяналтын соёлд санаа зовниж, гаднаас хүн томилох шаардлагатай гэж мэдэгджээ. Хуаныг эргэн ирэхийг уриалсан нээлттэй захидалд Нвидиагийн 10 мянга гаруй одоогийн болон хуучин ажилтан, тэр дундаа Илон Маск гарын үсэг зурсан байна.\n\nНвидиа өнөөдөр зах зээл хаагдсаны дараа гуравдугаар улирлын орлогын тайлангаа танилцуулах бөгөөд шинжээчид 109.1 тэрбум ам.долларын орлого, нэгж хувьцаанд 2.47 ам.долларын ашиг хүлээж байна. Энэ нь Хуаныг огцорсноос хойших анхны томоохон санхүүгийн шалгуур болох юм. Тус компанийн хувьцаа өнөөдөр 155.20 ам.доллар орчимд арилжаалагдаж байгаа бөгөөд дуулиан дэгдсэнээс хойш зах зээлийн үнэлгээ нь 700 тэрбум ам.доллараар буурсан байна.", textEn:"Nvidia co-founder Jensen Huang said today, November 17, that he would return as chief executive if the company's board asks him to. «If the Board of Directors decides that my return is in the best interest of our shareholders, our employees, the company, and America, I would be honored to answer these calls and return as CEO,» he wrote. It is his first public statement since he resigned last week.\n\nHuang stepped down on November 12 following reports of extramarital affairs, and Chief Financial Officer Colette Kress is now serving as interim CEO. The board is searching for a permanent successor and, according to reports, is not considering Huang's return. The board is still selecting a search firm and is considering internal and external candidates.\n\nUS President Donald Trump said on Monday that he «would not mind» Huang returning, while Treasury Secretary Scott Bessent said an outsider should be appointed, citing concerns about the company's compliance culture. An open letter calling for Huang's return has been signed by more than 10,000 current and former Nvidia employees, including Elon Musk.\n\nNvidia reports third-quarter earnings after the market closes today, with analysts expecting revenue of 109.1 billion US dollars and earnings of 2.47 dollars a share. It is the first major financial test since Huang's departure. The company's shares traded at around 155.20 dollars today, and its market value has fallen by 700 billion dollars since the scandal broke."},
  {id:13, cat:"tech", title:"Apple-ийн үйлчилгээ дотоод шинэчлэлтийн улмаас тасалдлаа", titleEn:"Apple services hit by outage caused by internal update", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20Apple%20Park%20dllu.jpg?width=760", text:"Apple компанийн App Store, iCloud, Apple Pay, Apple Music зэрэг үйлчилгээ өнөөдөр буюу арваннэгдүгээр сарын 17-нд олон мянган хэрэглэгчдэд тасалдлаа. Downdetector цахим хуудсанд бүртгэгдсэн гомдлын тоо үд дундын орчимд огцом нэмэгдэж, хэрэглэгчид дансандаа нэвтэрч чадахгүй, төхөөрөмжөө идэвхжүүлж чадахгүй, үүлэн үйлчилгээнд холбогдож чадахгүй байгаа тухай мэдээлсэн байна.\n\nApple компанийн мэдээлснээр тасалдал нь дотоод шинэчлэлтийн улмаас үүссэн бөгөөд кибер халдлагатай холбоогүй аж. «Манай олон систем дотоод шинэчлэлтийн улмаас өнөө өглөө тасалдсаны дараа эргэн ажиллаж байна. Үлдсэн системийг аль болох хурдан ажиллуулахаар ажиллаж байна» гэж компанийн төлөөлөгч мэдэгджээ.\n\nApple-ийн системийн байдлын хуудсанд App Store, Apple Music, AppleCare on Device үйлчилгээ тасалдсан, iCloud данс болон нэвтрэх үйлчилгээнд асуудал гарсан тухай тэмдэглэгдсэн байна. iCloud дансны асуудал өглөөний 11:45 цагт эхэлж, бүх хэрэглэгчдэд нөлөөлсөн гэж компани мэдээлжээ. Тасалдал нь зөвхөн АНУ-аар хязгаарлагдаагүй бөгөөд Бразил, Грек, Латви, Арабын Нэгдсэн Эмират зэрэг улсын хэрэглэгчид ч асуудал мэдээлсэн байна.\n\nҮдийн дараа Apple бүх үйлчилгээ хэвийн ажиллаж байна гэж мэдэгдсэн байна. Тасалдал нь Apple-ийн дэлгүүрүүдэд ч нөлөөлж, борлуулалт, засвар, хэрэглэгчийн үйлчилгээнд саад учруулсан гэж мэдээлжээ. Энэ явдал нь Chase банкны тасалдал болон Microsoft Outlook-ийн асуудлын дараа гарсан технологийн салбарын сүүлийн тасалдал болж байна.", textEn:"Apple's App Store, iCloud, Apple Pay, Apple Music and other services were disrupted for thousands of users today, November 17. Complaints recorded on the outage tracker Downdetector surged around midday, with users reporting that they could not sign in to their accounts, activate devices or access cloud services.\n\nApple said the outage was caused by an internal update and was not the result of a cyberattack. «Many of our systems are back up and running after an internal update caused some outages this morning. We're working to get the remaining systems online as soon as possible,» a company spokesperson said.\n\nApple's system status page listed outages affecting the App Store, Apple Music and AppleCare on Device, and problems with iCloud Account & Sign In. The company said the iCloud account issue began at 11:45 a.m. and affected all users. The disruption was not limited to the United States, with users in Brazil, Greece, Latvia and the United Arab Emirates also reporting problems.\n\nBy the afternoon, Apple said all services were operating normally. The outage also affected Apple stores worldwide, interfering with sales, repairs and customer service, according to reports. It follows a Chase Bank outage and Microsoft Outlook problems, the latest in a series of technology disruptions."},
  {id:14, cat:"sport", title:"М.С.Дони IPL-ээс зодог тайлж, Ченнай Супер Кингсийн зөвлөх болов", titleEn:"MS Dhoni retires from IPL and becomes Chennai Super Kings mentor", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/The%20President%2C%20Shri%20Ram%20Nath%20Kovind%20presenting%20the%20Padma%20Bhushan%20Award%20to%20Shri%20M.S.%20Dhoni%2C%20at%20the%20Civil%20Investiture%20Ceremony-II%2C%20at%20Rashtrapati%20Bhavan%2C%20in%20New%20Delhi%20on%20April%2002%2C%202018.jpg?width=760", text:"Энэтхэгийн крикетийн домог Махендра Сингх Дони өнөөдөр буюу арваннэгдүгээр сарын 17-нд IPL буюу Энэтхэгийн Премьер лигээс тоглогчийн хувиар зодог тайлж, Ченнай Супер Кингс багийн зөвлөхөөр томилогдсон тухай тус баг албан ёсоор мэдэгдлээ. Ингэснээр 45 настай хаалгачийн 18 жил үргэлжилсэн IPL-ийн карьер өндөрлөж байна.\n\nДони 2008 онд лиг байгуулагдсан цагаас Ченнай Супер Кингс багт тоглож, багийг таван удаа IPL-ийн аварга, хоёр удаа Аваргуудын лигийн аварга болгосон юм. Тэрбээр багийн түүхэн дэх хамгийн олон тоглолт хийсэн тоглогч бөгөөд 272 тоглолтод оролцож, 5314 оноо авсан нь багийн түүхэн дэх хоёр дахь өндөр үзүүлэлт юм. Түүний сүүлчийн тоглолт нь 2025 оны IPL-д Гужарат Титанс багийн эсрэг болсон байна.\n\nСүүлийн жилүүдэд Донигийн тоглолтод оролцох нь биеийн байдлаас шалтгаалан буурч байсан бөгөөд 2026 оны улирлыг бүхэлд нь шилбэний гэмтлийн улмаас өнжсөн байна. Тэрбээр 2023 оноос хойш өвдөгний асуудалтай тэмцэж байгаа юм. Багийн ахлагчийн албыг 2024 онд Рутурай Гайквад хүлээн авсан байна.\n\nБагийн эзэн Рупа Гурунат Дони бямба гарагт тоглогчдыг хадгалах асуудлыг хэлэлцсэн видео дуудлагын үеэр шийдвэрээ мэдэгдсэн гэж мэдээлжээ. Багийн гүйцэтгэх захирал Каси Висванатан Донигийн 7 дугаартай өмсгөлийг багийн хүндэтгэлийн тэмдэг болгон мөнхөлж магадгүй гэж мэдэгдсэн байна. Багийн эзэн Н.Шринивасан «Донигүйгээр Ченнай Супер Кингс гэж байхгүй» гэж мэдэгдсэн бөгөөд Дони 2027 оны улирлаас зөвлөхийн хувиар багтай хамт ажиллах юм.", textEn:"Indian cricket legend Mahendra Singh Dhoni has retired as a player in the Indian Premier League and will become the mentor of Chennai Super Kings, the franchise announced today, November 17. The 45-year-old wicketkeeper's 18-year IPL career has come to an end.\n\nDhoni has played for Chennai Super Kings since the league was founded in 2008, leading the team to five IPL titles and two Champions League T20 titles. He is the franchise's most-capped player, with 272 appearances and 5,314 runs, the second-highest total in the team's history. His last match was against Gujarat Titans in the 2025 IPL.\n\nIn recent seasons, Dhoni's appearances had become less frequent because of his physical condition, and he missed the entire 2026 season with a calf injury. He has also been battling a recurring knee issue since 2023. Ruturaj Gaikwad took over the captaincy in 2024.\n\nTeam owner Rupa Gurunath said Dhoni conveyed his decision during a video call on Saturday while discussing player retention plans. Chief executive Kasi Viswanathan said the franchise might retire Dhoni's iconic number 7 jersey as a tribute. Owner N. Srinivasan said «There is no CSK without MS Dhoni», and Dhoni will work with the team as a mentor from the 2027 season."},
  {id:15, cat:"sport", title:"Энэтхэг SAFF аварга шалгаруулах тэмцээнд 10 дахь удаагаа түрүүллээ", titleEn:"India win record-extending 10th SAFF Championship title", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/India%20starting%20XI%20vs%20Puerto%20Rico%202016.jpg?width=760", text:"Энэтхэгийн хөлбөмбөгийн шигшээ баг Өмнөд Азийн хөлбөмбөгийн холбооны буюу SAFF аварга шалгаруулах тэмцээний шигшээ тоглолтод Пакистаныг 2:1-ээр хожиж, арав дахь удаагаа аваргын цом хүртлээ. Шигшээ тоглолт Бангладешийн нийслэл Дакка хотын Үндэсний цэнгэлдэх хүрээлэнд болж, Энэтхэг аваргаа хамгаалсан байна.\n\nЭнэ ялалт нь Энэтхэгийн хувьд дээд амжилтыг ахиулсан арав дахь аваргын цом бөгөөд тус баг Өмнөд Азийн хөлбөмбөгт ноёрхлоо дахин баталгаажууллаа. Энэтхэг, Пакистаны шигшээ тоглолт нь бүс нутгийн хамгийн их хүлээлттэй тоглолтуудын нэг бөгөөд энэ удаагийн тоглолт ч ширүүн өрсөлдөөнтэй болсон байна.\n\nSAFF аварга шалгаруулах тэмцээн нь Өмнөд Азийн улс орнуудын хөлбөмбөгийн хамгийн нэр хүндтэй тэмцээн бөгөөд Энэтхэг тус тэмцээний түүхэн дэх хамгийн амжилттай баг хэвээр байна. Тус багийн арав дахь аваргын цом нь бүс нутгийн хөлбөмбөгт Энэтхэгийн тэргүүлэх байр суурийг дахин харуулсан үйл явдал боллоо.", textEn:"India's national football team beat Pakistan 2-1 in the final of the South Asian Football Federation, SAFF, Championship to win a record-extending 10th title. The final was played at the National Stadium in Dhaka, Bangladesh, where India retained their crown.\n\nThe victory is India's 10th championship title, extending their record and reaffirming their dominance of South Asian football. An India-Pakistan final is one of the most eagerly awaited fixtures in the region, and this match was a fiercely contested encounter.\n\nThe SAFF Championship is the most prestigious football tournament among South Asian nations, and India remain the most successful team in its history. The 10th title once again underlined India's leading position in regional football."},
  {id:16, cat:"soyol", title:"«Хурд» хамтлагийн «Норсон зүрх» мюзикл UG Palace-д тоглогдож байна", titleEn:"Khurd band's 'Norson Zurkh' musical plays at UG Palace", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Live%20rock%20concert%20performance%20featuring%20musicians%20playing%20guitar%20on%20stage%20at%20night%20with%20vibrant%20lighting%20effects.jpg?width=760", text:"Монголын рок хөгжмийн Төрийн соёрхолт «Хурд» хамтлаг үүсгэн байгуулагдсаны 35 жилийн ойг угтан «Норсон зүрх» бүрэн хэмжээний мюзиклийг үзэгчдийн хүртээл болгож байна. Тус мюзикл арваннэгдүгээр сарын 11-22-ны өдрүүдэд Улаанбаатар хотын UG Palace-д тоглогдож байгаа юм.\n\nМонголын тайзны урлагт шинэ хуудас нээх зорилготой энэхүү бүтээл нь олон улсын мюзиклийн үйлдвэрлэлийн жишиг, мэргэжлийн стандартад нийцүүлэн хэрэгжүүлж буй томоохон төсөл юм. «Хурд» хамтлаг уг бүтээлийг залуу уран бүтээлчидтэй хамтран туурвиж байгаа бөгөөд гол дүрүүдэд залуу артистууд тоглож байна.\n\nТөслийн санаачлагчаар Төрийн соёрхолт «Хурд» хамтлаг ажиллаж байгаа бол ерөнхий продюсерээр Гавьяат жүжигчин, хамтлагийн гитарчин Д.Отгонбаяр, продюсерээр ИБУИНХУ дахь Монгол Улсын Соёлын элч Ж.Өнөрмаа нар ажиллаж байна. Төслийн менежер, гүйцэтгэх продюсерээр О.Мөнхтуул, ерөнхий найруулагчаар «Про» театрын найруулагч, жүжигчин Б.Даваасүрэн, уран сайхны удирдаачаар Б.Анхбаатар, хөгжмийн найруулагчаар Урлагийн гавьяат зүтгэлтэн, хөгжмийн зохиолч Б.Чинбат, зохиолчоор Х.Чойдогжамц, зөвлөхөөр Төрийн шагналт, Урлагийн гавьяат зүтгэлтэн, найруулагч Н.Наранбаатар нар ажиллаж байгаа аж.\n\n«Норсон зүрх» мюзиклийг зөвхөн Монголын үзэгчдэд хүргээд зогсохгүй цаашид олон улсын тайзнаа толилуулах зорилт тавьжээ. Ийнхүү «Хурд» хамтлаг 35 жилийн ойн хүрээнд залуу уран бүтээлчидтэй хамтран Монголын рок хөгжим, театрын урлагийг хослуулсан шинэ бүтээлээр үзэгчидтэйгээ уулзаж байна.", textEn:"State Prize-winning Mongolian rock band Khurd is presenting the full-length musical «Norson Zurkh» (Wet Heart) to mark the 35th anniversary of the band's founding. The musical is playing at UG Palace in Ulaanbaatar from November 11 to 22.\n\nThe production, which aims to open a new chapter in Mongolian stage art, is a major project implemented to international musical production standards. Khurd created the work together with young artists, who play the leading roles.\n\nThe project was initiated by Khurd, with Honoured Artist and band guitarist D. Otgonbayar as general producer and J. Unurmaa, Mongolia's Cultural Envoy to the United Kingdom, as producer. The project manager and executive producer is O. Munkhtuul, the chief director is B. Davaasuren of the Pro Theatre, the artistic director is B. Ankhbaatar, the music director is Honoured Artist and composer B. Chinbat, the writer is Kh. Choidogjamts, and the consultant is State Prize laureate, Honoured Artist and director N. Naranbaatar.\n\nThe «Norson Zurkh» musical is intended not only for Mongolian audiences but also for the international stage in the future. With this new work combining Mongolian rock music and theatre art, Khurd is meeting its audiences as part of its 35th anniversary."},
  {id:17, cat:"soyol", title:"Төв аймагт Д.Нацагдоржийн 120 жилийн ойд зориулсан «Миний нутаг» яруу найргийн наадам боллоо", titleEn:"'My Homeland' poetry festival marks Natsagdorj's 120th anniversary in Tuv", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Juliusz%20S%C5%82owacki%20Theatre%20%28curtain%29.JPG?width=760", text:"Монголын орчин үеийн утга зохиолыг үндэслэгч, соён гэгээрүүлэгч, их зохиолч Д.Нацагдоржийн мэндэлсний 120 жилийн ойд зориулсан «Миний нутаг» яруу найргийн наадмыг Төв аймгийн Зуунмод хотын Монгол туургатан театрт гурав дахь жилдээ зохион байгууллаа.\n\nТөв аймгийн утга зохиол, яруу найраг сонирхогчдын дунд зарласан тус наадмын эхний шатанд 27 сумаас 50 гаруй бүтээл иржээ. Улмаар хоёрдугаар шатанд 22 сумын 25 яруу найрагчийн бүтээл шалгарсан байна. Дараагийн шатанд 10 оролцогч өөрсдийн зохиосон шүлгээр өрсөлдсөн бол шилдэг тавд шалгарсан яруу найрагчид өмнө нь олон нийтэд хүргэж байгаагүй шинэ бүтээлээ уншиж, авьяас чадвараа сорьжээ.\n\nНаадмын тэргүүн байрт Сэргэлэн сумаас оролцсон Д.Гомбосүрэн «Тив тивээр» шүлгээрээ шалгарсан бол дэд байрт Зуунмод сумын залуу яруу найрагч Тө.Бямбасүрэн «Урмын үг» шүлгээрээ орлоо. Мөн шилдэг 10-т шалгарсан оролцогчдод ардын уран зохиолчдын нэрэмжит шагнал гардуулжээ. Цаашид тус наадмыг хоёр жил тутамд зохион байгуулахаар болсон байна.\n\nД.Нацагдорж 1906 оны арваннэгдүгээр сарын 17-нд өнөөгийн Төв аймгийн Баяндэлгэр сумын нутагт мэндэлсэн бөгөөд энэ жил түүний мэндэлсний 120 жилийн ой тохиож байна. Ойн хүрээнд Улаанбаатар хотод түүний хөшөөнд цэцэг өргөх ёслол, «Хэлхээгүй сувд» яруу найргийн уншлага зэрэг арга хэмжээ зохион байгуулагдаж байгаа юм.", textEn:"The «My Homeland» poetry festival, dedicated to the 120th anniversary of the birth of D. Natsagdorj, founder of modern Mongolian literature, educator and great writer, was held for the third year at the Mongol Tuurgatan Theatre in Zuunmod, Tuv aimag.\n\nMore than 50 works from 27 soums were submitted to the first round of the festival, announced among literature and poetry lovers in Tuv aimag. In the second round, works by 25 poets from 22 soums were selected. In the next round, 10 participants competed with poems of their own, and the top five read new, previously unpublished works.\n\nFirst place went to D. Gombosuren from Sergelen soum for the poem «Tiv Tiviir», while second place went to young Zunmod poet Tu. Byambasuren for «Urmiin Ug». The top 10 participants also received prizes named after People's Writers. The festival will now be held every two years.\n\nD. Natsagdorj was born on November 17, 1906, in what is now Bayandelger soum, Tuv aimag, and this year marks the 120th anniversary of his birth. Events marking the anniversary include a flower-laying ceremony at his statue in Ulaanbaatar and a poetry reading of «Khelkheegui Suvd»."},
  {id:18, cat:"delhii", title:"«Акван» циклон Энэтхэгийн эрэгт ойртож байна", titleEn:"Cyclone Akvan approaches India's coast", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Cyclone%20Mocha%20Forms%20in%20Bay%20of%20Bengal%20%28CIRA%202023-05-11%29.png?width=760", text:"Бенгалын буланд үүссэн «Акван» циклон хүчээ авч, арваннэгдүгээр сарын 20-нд Энэтхэгийн Андхра Прадеш мужийн эрэгт 120 км/цаг хүртэлх салхитайгаар хүрэх төлөвтэй байгаа тухай Энэтхэгийн цаг уурын газар мэдээллээ. Циклоны улмаас эрэг орчмын нутгаар хүчтэй салхи, аадар бороо орох төлөвтэй байна.\n\nЦиклоны улмаас Ченнай хотоос Янгон чиглэлийн долоо хоног тутмын нислэг хоёр чиглэлд цуцлагдсан бөгөөд 144 зорчигч эх орондоо буцахаас өөр аргагүй болсон байна. Дараагийн нислэг ирэх долоо хоногт үйлдэгдэх юм. Эрэг орчмын нутгийн иргэдэд сонор сэрэмжтэй байхыг анхааруулж байна.\n\nЦиклон нь Бенгалын булангаар дамжин өнгөрч, Энэтхэгийн зүүн эрэг болон Мьянмарын чиглэлд нөлөөлөх төлөвтэй байна. Цаг уурын байгууллага циклоны хөдөлгөөнийг тогтмол ажиглаж, иргэдэд цаг агаарын мэдээг тогтмол авахыг зөвлөж байна.", textEn:"Cyclone Akvan, which formed in the Bay of Bengal, is intensifying and is expected to hit the coast of Andhra Pradesh, India, on November 20 with winds of up to 120 kilometres per hour, the India Meteorological Department said. Strong winds and heavy rain are expected in coastal areas.\n\nBecause of the cyclone, the weekly flight from Chennai to Yangon has been cancelled in both directions, and 144 passengers have had to return home. The next flight will operate next week. Residents of coastal areas have been urged to remain vigilant.\n\nThe cyclone is expected to pass through the Bay of Bengal and affect India's eastern coast and Myanmar. The weather agency is monitoring the cyclone's movement and advises residents to follow weather updates regularly."},
];

function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-11-18", items:[
  {code:"USD", mnt:3603.85, chg:1}, {code:"EUR", mnt:3962.97, chg:-1}, {code:"JPY", mnt:22.62, chg:1},
  {code:"CNY", mnt:540.62, chg:1}, {code:"KRW", mnt:2.69, chg:-1}, {code:"RUB", mnt:43.78, chg:-1}, {code:"GBP", mnt:4752.58, chg:-1}
]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-14, code:3},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:11, code:0},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:6, code:3},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:0, code:0},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:0, code:3}
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

